window.docContents[172].resolve({"/Elementary-Functions/___4___42-Solution-of-Triangles/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___42-Solution-of-Triangles--___4___42-Solution-of-Triangles--Planar-right-triangles":{"contents":"The right-triangle ratios are the elementary definitions of sine, cosine, and\ntangent in the source figure.  The hypotenuse is positive, and the acute-angle\nhypothesis excludes the degenerate endpoints; the arcsin compatibility\nrecords that A is the angle opposite height a.\n\n\\sin A=\\frac{a}{c}=\\frac{1}{\\csc A}$$\n\n\\cos A=\\frac{b}{c}=\\frac{1}{\\sec A}$$\n\n\\tan A=\\frac{a}{b}=\\frac{1}{\\cot A}$$\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.42 Solution of Triangles\u0009§4.42 Solution of Triangles","header":"Planar right triangles","id":"/Elementary-Functions/___4___42-Solution-of-Triangles/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___42-Solution-of-Triangles--___4___42-Solution-of-Triangles--Planar-right-triangles"},"/Incomplete-Gamma-and-Related-Functions/Chapter-contents/#LMLF-___-DLMF-with-Lean--Incomplete-Gamma-and-Related-Functions--Chapter-contents--Applications-and-computation":{"contents":"* 8.22 Mathematical Applications* 8.23 Statistical Applications* 8.24 Physical Applications* 8.25 Methods of Computation* 8.26 Tables* 8.27 Approximations* 8.28 Software\n\n","context":"LMLF · DLMF with Lean\u0009Incomplete Gamma and Related Functions\u0009Chapter contents","header":"Applications and computation","id":"/Incomplete-Gamma-and-Related-Functions/Chapter-contents/#LMLF-___-DLMF-with-Lean--Incomplete-Gamma-and-Related-Functions--Chapter-contents--Applications-and-computation"}});